pieces=[]
for hour in range(1,13):
    datum=trace[str(hour)]
    s=number_h*datum["height_px"]/180.0
    glyph=None
    for ring in datum["outer"]:
        face=Polygon(*[(x*s,y*s) for x,y in ring],align=None)
        glyph=face if glyph is None else glyph+face
    for ring in datum["holes"]:
        glyph=glyph-Polygon(*[(x*s,y*s) for x,y in ring],align=None)
    a=math.radians(hour*30)
    number=Pos(number_radius*math.sin(a),number_radius*math.cos(a))*extrude(glyph,amount=relief,dir=(0,0,1))
    assert len(number.solids())==len(str(hour))
    assert number.bounding_box().min.Z > -0.00001
    assert abs(number.bounding_box().max.Z-relief)<0.00001
    for solid in number.solids():
        solid.color=Color(1.0,1.0,1.0)
        pieces.append(solid)
assert len(pieces)==15
numerals=Compound(children=pieces)
numerals.color=Color(1.0,1.0,1.0)
publish("numerals",numerals,"Reference traced numerals",material="petg")